  "sim.egg-incubator.title": "Yumurta Kuluçka Makinesi",
  "sim.egg-incubator.desc": "Kuluçkahane içinde sıcaklığı, nemi ve yumurta dönüşünü yöneterek çıkım oranını maksimize edin.",
  "sim.dairy-farm.title": "Süt Çiftliği",
  "sim.dairy-farm.desc": "Küçük bir süt işletmesi yürütün: yem planları, sağım döngüleri ve sürü sağlığıyla verimi maksimize edin.",
  "sim.poultry-farm.title": "Kanatlı Çiftliği",
  "sim.poultry-farm.desc": "Ticari bir kanatlı çiftliği yönetin — yem, sağlık ve üretim hedefleriyle etlik ve damızlık sürüleri yönetin.",
  "sim.cattle-dairy.title": "Sığır & Süt",
  "sim.cattle-dairy.desc": "Bir sığır çiftliği ve süt birimini yönetin; mera yönetimi, çiftleştirme ve süt üretimini dengeleyin.",
  "sim.sheep-farm.title": "Koyun Çiftliği",
  "sim.sheep-farm.desc": "Mevsimsel döngülerle bir koyun çiftliği yürütün: kuzu doğumu, kırkım ve piyasa satışları.",
  "sim.network-noc.title": "Network NOC",
  "sim.network-noc.desc": "Ağ Operasyonları Merkezi mühendisi gibi hareket edin — baskı altında canlı altyapı olaylarını teşhis edin ve çözün.",
  "sim.mobile-repair.title": "Mobil Tamir Atölyesi",
  "sim.mobile-repair.desc": "Akıllı telefonları teşhis edin ve onarın — ekran değişimleri, pil sorunları ve anakart arızaları.",
  "sim.laptop-repair.title": "Dizüstü Bilgisayar Tamir Atölyesi",
  "sim.laptop-repair.desc": "Dizüstü bilgisayarları sorun giderin ve onarın: donanım arızaları, BIOS sorunları ve parça değişimleri.",
  "sim.perfume-lab.title": "Parfüm Laboratuvarı",
  "sim.perfume-lab.desc": "Esansiyel yağları ve aroma bileşenlerini harmanlayın; özgün kokular oluşturun ve kalite hedeflerini yakalayın.",
  "sim.detergent-lab.title": "Deterjan Laboratuvarı",
  "sim.detergent-lab.desc": "Temizlik ürünleri formüle edin — bütçe içinde yüzey aktifler, dolgu maddeleri ve performans testlerini dengeleyin.",
  "sim.skin-care-lab.title": "Cilt Bakım Laboratuvarı",
  "sim.skin-care-lab.desc": "Kozmetik formülasyonları geliştirin ve test edin; güvenlik standartlarını ve etkinlik hedeflerini karşılayın.",
  "sim.woodworking.title": "Marangozluk Atölyesi",
  "sim.woodworking.desc": "Özel bir marangozluk atölyesi işletin: iş planlayın, malzemeleri yönetin ve mobilyaları zamanında ve bütçe dahilinde teslim edin.",
  "sim.aluminum-glazing.title": "Alüminyum & Cam",
  "sim.aluminum-glazing.desc": "Tekliften şantiye tamamlanmasına kadar bir alüminyum imalat ve cam montaj işi yönetin.",
  "sim.global-kitchen.title": "Küresel Mutfak",
  "sim.global-kitchen.desc": "Bir restoran mutfağını yönetin: servis vardiyalarında menüleri, personeli, maliyetleri ve müşteri memnuniyetini yönetin.",
  "sim.chocolate-factory.title": "Çikolata Fabrikası",
  "sim.chocolate-factory.desc": "Bir şekerleme fabrikası işletin — kakao temini, üretim planlama ve kalite kontrol.",
  "sim.solar-energy.title": "Güneş Enerjisi Santrali",
  "sim.solar-energy.desc": "Bir güneş kurulumu tasarlayın ve işletin — panelleri boyutlandırın, şebeke ihracını yönetin ve yatırım getirisini takip edin.",
  "sim.hvac-systems.title": "HVAC Sistemleri",
  "sim.hvac-systems.desc": "Ticari binalar için ısıtma, havalandırma ve klima sistemlerini kurun ve bakımını yapın.",
  "sim.logistics-supply.title": "Lojistik & Tedarik Zinciri",
  "sim.logistics-supply.desc": "Depo operasyonlarını, filo rotalarını ve tedarikçi ilişkilerini optimize ederek teslimat KPI'larını yakalayın.",
  "sim.barber-salon.title": "Berber Salonu",
