  "jungle.howTo.1": "Kendini ormanda mahsur kalmış halde buluyorsun — hayatta kalma tercihlerinde bulun",
  "jungle.howTo.2": "Her seçim HP ve skorunu farklı şekilde etkiler",
  "jungle.howTo.3": "HP'in 0'a ulaşırsa oyun biter",
  "jungle.howTo.4": "Kazanmakiçin tüm 8 senaryoyu atlat!",
  "jungle.scene6": "Yaralı bir kuş buluyorsun. Ne yaparsın?",
  "jungle.s6c1": "Dikkatlice taşı — sana bir yola çıkarabilir (+5 HP, +25 puan)",
  "jungle.s6c2": "Bırak — bakmak enerji harcatır (0 HP, +10 puan)",
  "jungle.scene7": "Bir nehir yolunu kapatıyor. Su hızlı görünüyor.",
  "jungle.s7c1": "Düşmüş kütüklerden bir sal yap (−5 HP, +40 puan)",
  "jungle.s7c2": "Sığ geçiş bulmak için yukarı doğru yürü (+10 HP, +20 puan)",
  "jungle.scene8": "Uzakta duman görüyorsun.",
  "jungle.s8c1": "Dumana doğru git — belki kurtarma var! (+15 HP, +45 puan)",
  "jungle.s8c2": "Onun yerine uzak dur — bir orman yangını olabilir (−5 HP, +15 puan)",
  "jungle.scene9": "Gece çökmeye başlıyor. Barınağa ihtiyacın var.",
  "jungle.s9c1": "Avcılardan korunmak için yüksek bir ağaca tırman (+10 HP, +30 puan)",
  "jungle.s9c2": "Dallarla yer barınağı inşa et (−5 HP, +35 puan)",
  "jungle.scene10": "Tanımadığın bir meyve buluyorsun. Çok açsın.",
  "jungle.s10c1": "Ye — açlıktan ölüyorsun! (−20 HP, +30 puan)",
  "jungle.s10c2": "Önce cildinde küçük bir parça dene (0 HP, +20 puan)",
  "jungle.scene11": "Yolda büyük bir yılan dolanıyor.",
  "jungle.s11c1": "Yavaşça geri çek ve dolambaçlı bir yol bul (+5 HP, +30 puan)",
  "jungle.s11c2": "Onu korkutup uzaklaştırmayı dene (−25 HP, +40 puan)",
  "jungle.scene12": "Bir şelale sesi duyuyorsun — su kaynakların kritik seviyede düşük.",
  "jungle.s12c1": "Sesi takip et ve taze su bul (+20 HP, +35 puan)",
  "jungle.s12c2": "Aldırma ve ileri gitmeye devam et (−15 HP, +20 puan)",
  "jungle.scene13": "Fırtına hızla yaklaşıyor.",
  "jungle.s13c1": "Yüksek zemini bul ve korun ( +10 HP, +25 puan)",
  "jungle.s13c2": "Kaçmak için hareket etmeye devam et (−10 HP, +30 puan)",
  "jungle.scene14": "Bir mağara buluyorsun. Hava kararıyor.",
  "jungle.s14c1": "Barınmak için mağaraya gir (+15 HP, +30 puan)",
  "jungle.s14c2": "Bir ağacın altında uyuyorsun — mağara dolu olabilir (+5 HP, +20 puan)",
  "jungle.scene15": "Çok yorgunsun. İlerdeki açıklık güvenli görünüyor.",
  "jungle.s15c1": "Dinlen ve toparlan (+20 HP, +20 puan)",
  "jungle.s15c2": "Devam et — burada dinlenmek tehlikeli (−5 HP, +30 puan)",
  "jungle.scene16": "Bir ağaca oyulmuş eski bir harita buluyorsun.",
  "jungle.s16c1": "Haritanın yönünü takip et (+5 HP, +40 puan)",
  "jungle.s16c2": "Aldırma — güncel olmayabilir (0 HP, +10 puan)",
  "jungle.scene17": "Yaban domuzları saldırgan şekilde yolunu kesiyor.",
  "jungle.s17c1": "Hemen en yakın ağaca tırman (+5 HP, +30 puan)",
  "jungle.s17c2": "Olduğun yerde dur ve bağır (−20 HP, +35 puan)",
  "jungle.scene18": "İçinde erzak olan terk edilmiş bir kamp buluyorsun.",
  "jungle.s18c1": "İşe yarayan her şeyi al (+20 HP, +50 puan)",
  "jungle.s18c2": "Bırak — biri daha sonra ihtiyaç duyabilir (0 HP, +10 puan)",
  "jungle.scene19": "Bir maymun yiyecek çantanı çalıyor!",
  "jungle.s19c1": "Maymunu kovalayın (−10 HP, +40 puan)",
  "jungle.s19c2": "Bırak gitsin — harcanan enerjiye değmez (+0 HP, +15 puan)",
  "jungle.scene20": "Üzerinizde bir helikopter sesi duyuyorsunuz.",
  "jungle.s20c1": "Hemen bir sinyal ateşi yakın! (+30 HP, +60 puan)",
  "jungle.s20c2": "Kollarınızı sallayın — belki sizi görür (+5 HP, +40 puan)",
